function fixedMatch(left, right) {
  if (typeof left !== "string" || typeof right !== "string" || left.length !== right.length)
    return false;
  let diff = 0;
  for (let i = 0; i < left.length; i++) diff |= left.charCodeAt(i) ^ right.charCodeAt(i);
  return diff === 0;
}

function challenge(query, secret) {
  const token = query?.["hub.verify_token"];
  const value = query?.["hub.challenge"];
  if (
    typeof secret !== "string" ||
    secret.length < 24 ||
    !fixedMatch(token, secret) ||
    query?.["hub.mode"] !== "subscribe" ||
    typeof value !== "string" ||
    !/^[\x21-\x7e]{1,256}$/.test(value)
  ) {
    return { status: 403, body: "" };
  }
  return { status: 200, body: value };
}

let token;
try {
  token = $env.META_WHATSAPP_VERIFY_TOKEN;
} catch {}
return { json: challenge($json.query, token) };

function signedRequest(bytes, headers) {
  const waha = headers["x-webhook-hmac"];
  const meta = headers["x-hub-signature-256"];
  const validType = /^application\/json(?:\s*;|$)/i.test(headers["content-type"] ?? "");
  if (
    !validType ||
    (headers["content-encoding"] !== undefined && headers["content-encoding"] !== "identity") ||
    !bytes ||
    bytes.length === 0 ||
    bytes.length > 1048576
  )
    return {};
  const raw = bytes.toString("utf8");
  // n8n's Crypto HMAC accepts UTF-8 text. Refuse invalid sequences instead of rewriting signed bytes.
  if (!Buffer.from(raw, "utf8").equals(bytes)) return {};
  if (
    meta === undefined &&
    typeof waha === "string" &&
    /^[a-f0-9]{128}$/.test(waha) &&
    headers["x-webhook-hmac-algorithm"] === "sha512"
  ) {
    return { raw, digest: waha, provider: "waha" };
  }
  if (waha === undefined && typeof meta === "string" && /^sha256=[a-f0-9]{64}$/.test(meta)) {
    return { raw, digest: meta.slice(7), provider: "meta" };
  }
  return {};
}

let raw;
try {
  raw = await helpers.getBinaryDataBuffer($itemIndex, "data");
} catch {}
return { json: signedRequest(raw, $json.headers ?? {}) };

function fixedMatch(left, right) {
  if (typeof left !== "string" || typeof right !== "string" || left.length !== right.length)
    return false;
  let diff = 0;
  for (let i = 0; i < left.length; i++) diff |= left.charCodeAt(i) ^ right.charCodeAt(i);
  return diff === 0;
}

function authorizedBody(signature, computed) {
  if (!signature.provider || !fixedMatch(signature.digest, computed)) return { status: 401 };
  try {
    const body = JSON.parse(signature.raw);
    if (typeof body !== "object" || body === null || Array.isArray(body)) return { status: 400 };
    return { status: 200, provider: signature.provider, body };
  } catch {
    return { status: 400 };
  }
}

return { json: authorizedBody($("Read the original signed bytes").item.json, $json.computed) };

function normalizedPhone(value) {
  if (typeof value !== "string" || !/^\+?\d{8,15}$/.test(value)) return "";
  const digits = value.replace(/^\+/, "");
  if (/^0\d{8,9}$/.test(digits)) return "+972" + digits.slice(1);
  if (digits.startsWith("0")) return "";
  return "+" + digits;
}

function cleanName(name) {
  const text =
    typeof name === "string"
      ? name
          .replace(/[\u0000-\u001f\u007f]/g, " ")
          .trim()
          .slice(0, 120)
      : "";
  return text || "New WhatsApp lead";
}

function leadConfig(settings, provider) {
  if (
    typeof settings.spreadsheetId !== "string" ||
    !/^[a-zA-Z0-9_-]{10,160}$/.test(settings.spreadsheetId) ||
    settings.spreadsheetId.startsWith("YOUR_") ||
    !Number.isInteger(settings.tabId) ||
    settings.tabId < 0 ||
    settings.tabId > 2147483647
  ) {
    throw new Error("Configure a dedicated leads spreadsheet and numeric tab ID.");
  }
  if (
    provider === "waha" &&
    (!/^[a-zA-Z0-9_-]{1,60}$/.test(settings.wahaSession) ||
      !/^https:\/\/[a-zA-Z0-9.-]+(?::\d{1,5})?$/.test(settings.wahaOrigin) ||
      settings.wahaOrigin === "https://waha.example.com")
  ) {
    throw new Error("Configure the HTTPS WAHA origin and session.");
  }
  if (provider === "meta" && !/^\d{5,30}$/.test(settings.metaPhoneId)) {
    throw new Error("Configure the Meta business phone number ID.");
  }
  return settings;
}

function whatsappLeads(body, provider, settings, arrivedAt) {
  const leads = [];
  const cleanup = (data, identity, address, chatName, message, phone, replyUntil) => {
    if (
      typeof identity !== "string" ||
      identity.length === 0 ||
      identity.length > 240 ||
      /[\u0000-\u001f\u007f]/.test(identity)
    )
      return;
    const name = cleanName(chatName);
    const text = typeof message === "string" ? message.slice(0, 16000) : "";
    const key = JSON.stringify([provider, data, identity]);
    leads.push({
      provider,
      scope: data,
      address,
      name,
      message: text,
      phone,
      replyUntil,
      key,
      arrivedAt,
      spreadsheetId: settings.spreadsheetId,
      tabId: settings.tabId,
      wahaOrigin: settings.wahaOrigin,
    });
  };
  if (provider === "waha") {
    const p = body.payload;
    if (
      body.event !== "message" ||
      body.session !== settings.wahaSession ||
      !p ||
      p.fromMe !== false ||
      typeof p.from !== "string" ||
      !/^\d{8,20}@(c\.us|lid)$/.test(p.from)
    )
      return [];
    const lid = p.from.endsWith("@lid");
    const phone = lid ? "" : normalizedPhone(p.from.slice(0, -5));
    if (!lid && !phone) return [];
    cleanup(body.session, p.id, p.from, p._data?.notifyName ?? p.notifyName, p.body, phone, null);
  } else {
    if (body.object !== "whatsapp_business_account" || !Array.isArray(body.entry)) return [];
    for (const entry of body.entry) {
      for (const change of Array.isArray(entry?.changes) ? entry.changes : []) {
        const v = change?.value;
        if (
          change?.field !== "messages" ||
          v?.messaging_product !== "whatsapp" ||
          v?.group_id ||
          v?.metadata?.phone_number_id !== settings.metaPhoneId ||
          !Array.isArray(v.messages)
        )
          continue;
        for (const msg of v.messages) {
          if (
            !msg ||
            msg.fromMe === true ||
            msg.group_id ||
            msg.context?.group_id ||
            typeof msg.from !== "string" ||
            !/^[1-9]\d{7,14}$/.test(msg.from)
          )
            continue;
          const contact = Array.isArray(v.contacts)
            ? v.contacts.find((contact) => contact?.wa_id === msg.from)
            : undefined;
          const elapsed = Date.parse(arrivedAt) - Number(msg.timestamp) * 1000;
          const canReply =
            Number.isFinite(elapsed) && elapsed >= -5 * 60000 && elapsed < 24 * 3600000;
          cleanup(
            settings.metaPhoneId,
            msg.id,
            msg.from,
            contact?.profile?.name,
            msg.text?.body,
            normalizedPhone(msg.from),
            canReply ? Number(msg.timestamp) * 1000 + 24 * 3600000 : 0,
          );
        }
      }
    }
  }
  const seen = new Set();
  return leads.filter((item) => {
    if (seen.has(item.key)) return false;
    seen.add(item.key);
    return true;
  });
}

const { provider, body, status } = $input.first().json;
if (status !== 200) return [];
const settings = {
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  tabId: 0,
  wahaOrigin: "https://waha.example.com",
  wahaSession: "default",
  metaPhoneId: "YOUR_META_PHONE_NUMBER_ID",
};
const config = leadConfig(settings, provider);
return whatsappLeads(body, provider, config, new Date().toISOString()).map((json) => ({
  json,
  pairedItem: { item: 0 },
}));

function normalizedPhone(value) {
  if (typeof value !== "string" || !/^\+?\d{8,15}$/.test(value)) return "";
  const digits = value.replace(/^\+/, "");
  if (/^0\d{8,9}$/.test(digits)) return "+972" + digits.slice(1);
  if (digits.startsWith("0")) return "";
  return "+" + digits;
}

function withLidPhone(lead, result, code) {
  if (
    code !== 200 ||
    result?.lid !== lead.address ||
    typeof result.pn !== "string" ||
    !/^[0-9]{8,15}@c\.us$/.test(result.pn)
  ) {
    return { state: "unresolved_lid", ready: false };
  }
  const phone = normalizedPhone(result.pn.slice(0, -5));
  return phone ? { ...lead, phone, ready: true } : { state: "unresolved_lid", ready: false };
}

return {
  json: withLidPhone($("Select direct incoming leads").item.json, $json.body, $json.statusCode),
};

function leadPlan(lead, digest) {
  if (!/^[a-f0-9]{64}$/.test(digest))
    throw new Error("Could not fingerprint the provider message.");
  // The Sheets ID is only the atomic reservation slot. Compare the full provider identity on reads.
  const id = (parseInt(digest.slice(0, 8), 16) % 2147483647) + 1;
  const metadata = {
    metadataId: id,
    metadataKey: "whatsapp-lead-message-v1",
    metadataValue: lead.key,
    visibility: "DOCUMENT",
    location: { sheetId: lead.tabId },
  };
  const cells = [lead.arrivedAt, lead.name, lead.phone, lead.message, "WhatsApp"].map(
    (stringValue) => ({ userEnteredValue: { stringValue } }),
  );
  const request = {
    requests: [
      { createDeveloperMetadata: { developerMetadata: metadata } },
      {
        appendCells: { sheetId: lead.tabId, rows: [{ values: cells }], fields: "userEnteredValue" },
      },
    ],
  };
  return {
    ...lead,
    metadata,
    request,
    root: "https://sheets.googleapis.com/v4/spreadsheets/" + lead.spreadsheetId,
  };
}

return { json: leadPlan($json, $json.digest) };

function matchMetadata(expected, actual) {
  return (
    actual?.metadataId === expected.metadataId &&
    actual.metadataKey === expected.metadataKey &&
    actual.metadataValue === expected.metadataValue &&
    actual.visibility === expected.visibility &&
    actual.location?.sheetId === expected.location.sheetId
  );
}

function claimStatus(plan, response) {
  if (response.statusCode === 404) return { ...plan, ready: true };
  if (response.statusCode !== 200) return { state: "metadata_read_unconfirmed", ready: false };
  if (matchMetadata(plan.metadata, response.body))
    return { state: "already_recorded", ready: false };
  return { state: "metadata_slot_occupied", ready: false };
}

return { json: claimStatus($("Prepare the metadata reservation and row").item.json, $json) };

function matchMetadata(expected, actual) {
  return (
    actual?.metadataId === expected.metadataId &&
    actual.metadataKey === expected.metadataKey &&
    actual.metadataValue === expected.metadataValue &&
    actual.visibility === expected.visibility &&
    actual.location?.sheetId === expected.location.sheetId
  );
}

function replyPlan(lead, response, now) {
  const body = response?.body;
  if (
    response.statusCode !== 200 ||
    body?.spreadsheetId !== lead.spreadsheetId ||
    body.replies?.length !== 2 ||
    !matchMetadata(lead.metadata, body.replies[0]?.createDeveloperMetadata?.developerMetadata)
  ) {
    return { state: "check_sheet_before_replying", ready: false };
  }
  if (lead.provider === "meta" && !(Number(now) < lead.replyUntil)) {
    return { state: "lead_recorded_without_reply", ready: false };
  }
  const text = "תודה " + lead.name + "! קיבלנו את הפנייה שלך ונחזור אליך בהקדם 🙏";
  if (lead.provider === "waha")
    return {
      ready: true,
      waha: true,
      url: lead.wahaOrigin + "/api/sendText",
      request: { session: lead.scope, chatId: lead.address, text },
    };
  return {
    ready: true,
    waha: false,
    url: "https://graph.facebook.com/v25.0/" + lead.scope + "/messages",
    request: {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to: lead.address,
      type: "text",
      text: { body: text },
    },
  };
}

return {
  json: replyPlan(
    $("Classify new, duplicate or conflicting messages").item.json,
    $json,
    Date.now(),
  ),
};

const { body, statusCode } = $json;
const id = typeof body?.id === "string" ? body.id : body?.id?._serialized;
return {
  json: {
    state:
      statusCode >= 200 && statusCode < 300 && typeof id === "string" && id
        ? "reply_confirmed"
        : "check_original_chat_before_replying",
  },
};

const { body, statusCode } = $json;
return {
  json: {
    state:
      statusCode >= 200 && statusCode < 300 && typeof body?.messages?.[0]?.id === "string"
        ? "reply_confirmed"
        : "check_original_chat_before_replying",
  },
};
